def hello(name):
    return b'Hello, %s!' % name
@@;

$udf = SystemPython3_8::hello(Callable<(String)->String>, $script);

SELECT $udf("world"); -- "Hello, world!"

$script = @@#py
def concat(a, b):
    return a.decode("utf-8") + str(b)
